/* 江湖一生 · incidents: more of the life cycle — childhood, youth, family, property, old age */
'use strict';
{
const L2has=(s,id)=>s.items.some(i=>i.id===id);
const L2drop=(s,id)=>{const i=s.items.findIndex(x=>x.id===id);if(i>=0)s.items.splice(i,1)};
const L2kid=(s,a,b)=>living(s,'child').filter(p=>p.age>=a&&p.age<=b);
const L2sk=k=>k.sex==='m'?T('son','儿子'):T('daughter','女儿');
const L2kidCtx=(a,b)=>s=>{const k=pick(L2kid(s,a,b));return{k,who:k.id}};
const L2spCtx=s=>{const p=spouseOf(s);return{p,who:p.id}};
const L2he=p=>p.sex==='m'?'he':'she', L2him=p=>p.sex==='m'?'him':'her', L2ta=p=>p.sex==='m'?'他':'她';

/* ================= childhood (5–12) ================= */
I({id:'l2_inkstone',age:[6,12],once:1,text:()=>T('The teacher’s prized inkstone is found cracked. You saw who did it: the teacher’s own son.','先生最心爱的砚台裂了。你看见是谁干的：先生自己的儿子。'),
 opts:[{l:T('Tell the teacher','告诉先生'),out:[{w:2,t:T('The teacher goes very quiet, thanks you, and never calls on you again.','先生沉默了很久，谢了你，从此再也没点过你的名。'),c:'muted',fx:{align:3,smarts:-1}},{w:1,t:T('The teacher praises your honesty in front of the class. His son waits for you after school.','先生当众夸你诚实。他儿子放学后在门口堵你。'),fx:{align:3,hurt:[2,6],cause:T('a schoolyard grudge','学堂里的私怨')}}]},
  {l:T('Keep quiet','不吭声'),out:[{w:2,t:T('A poor boy is blamed and beaten. You carry it for years.','一个穷孩子替人挨了打。这件事你记了很多年。'),c:'bad',fx:{align:-3,happy:-3}},{w:1,t:T('The son confesses on his own. You feel small.','先生的儿子自己认了错。你觉得自己很渺小。'),c:'muted',fx:{align:-1}}]},
  {l:T('Tell the son you saw','告诉他你看见了'),out:[{w:2,t:T('He confesses, and afterwards shares his books with you.','他去认了错，后来还把自己的书借给你看。'),c:'good',fx:{smarts:4,align:2,meet:'friend',bond:60}},{w:1,t:T('He bribes you with a honey cake. It is a very good honey cake.','他用一块蜜糕收买了你。那块蜜糕真好吃。'),fx:{happy:3,align:-2}}]}]});

I({id:'l2_waterpole',age:[6,12],cd:6,text:()=>T('Your chore this year is carrying water from the river, two buckets on a pole, twenty trips a day.','今年你的活是从河边挑水，一根扁担两只桶，一天二十趟。'),
 out:[{w:2,t:T('Your shoulders burn, then harden. Your stance is steadier than any of the other children’s.','肩膀先是火辣辣地疼，后来磨出了茧。你下盘比别的孩子都稳。'),c:'good',fx:{skill:2,maxHealth:2}},
  {w:2,t:T('You rig a rope and pulley over the bank. It works for a week, then drops a bucket on your foot.','你在河岸上弄了个绳索滑轮。好用了一个星期，然后一只桶砸在了你脚上。'),fx:{smarts:3,hurt:[2,5],cause:T('a falling bucket','掉下来的水桶')}},
  {w:1,t:T('A passing swordsman watches you and says, "Don’t spill. That is the whole secret." You think about it for years.','一个路过的剑客看了你一会儿，说："别洒出来。全部的诀窍就这一句。"这句话你琢磨了好多年。'),c:'gold',fx:{qi:4}},
  {w:1,t:T('You pay a younger child one copper a day to do half of it. Business, at age eight.','你每天给一个更小的孩子一文钱，让他替你挑一半。小小年纪就会做生意了。'),fx:{smarts:2,money:-3,align:-1}}]});

I({id:'l2_roofrunner',age:[5,12],cd:8,text:()=>T('Late at night you see a figure in black running across the rooftops, light as a cat.','深夜，你看见一个黑衣人在屋顶上飞奔，轻得像一只猫。'),
 opts:[{l:T('Climb out and follow','爬出去跟着'),out:[{w:2,t:T('You fall off the woodshed. The figure stops, looks back, and laughs softly.','你从柴房顶上摔了下来。那人停下回头，轻轻笑了一声。'),fx:{hurt:[3,8],cause:T('falling off a roof','从屋顶摔下')}},{w:1,t:T('You follow as far as the temple. A sack of rice is left on the steps of the poorest family in the village.','你一直跟到庙前。全村最穷那户人家的门口多了一袋米。'),c:'good',fx:{align:5,happy:4}},{w:1,t:T('You lose them, but find a dropped dart with a plum blossom carved on it.','你跟丢了，却捡到一枚刻着梅花的飞镖。'),c:'gold',fx:{skill:2,flag:'l2_plumdart'}}]},
  {l:T('Wake your father','叫醒父亲'),out:[{w:2,t:T('He looks, sees nothing, and sends you back to bed.','他看了看，什么也没看见，把你赶回去睡觉。'),c:'muted'},{w:1,t:T('He looks, goes pale, and bars the door. In the morning the magistrate’s strongbox is empty.','他看了一眼，脸色发白，把门闩上了。第二天，县太爷的银箱空了。'),fx:{smarts:2}}]},
  {l:T('Wave','挥手'),out:[{w:2,t:T('The figure waves back. Nobody believes you.','那人也冲你挥了挥手。没有人相信你。'),fx:{happy:5}},{w:1,t:T('Next morning there is a sugar figurine on your windowsill.','第二天早上，你的窗台上多了一个糖人。'),c:'good',fx:{happy:6}}]}]});

I({id:'l2_missinghens',age:[6,12],once:1,text:()=>T('The neighbour’s hens are vanishing, one every night. The grown-ups blame the fox.','邻居家的鸡每晚少一只。大人们都说是狐狸干的。'),
 opts:[{l:T('Keep watch all night','守夜'),out:[{w:2,t:T('It is a weasel, as long as your arm. You chase it off with a broom and become a small hero.','是一只黄鼠狼，有你胳膊那么长。你用扫帚把它赶走了，成了个小英雄。'),c:'good',fx:{fame:1,happy:5}},
   {w:1,t:T('It is the neighbour’s own son, selling them in town to pay a gambling debt. He begs you not to tell.','是邻居家的儿子，偷去镇上卖了还赌债。他求你别说出去。'),c:'muted',fx:{smarts:3}},
   {w:1,t:T('It is a starving man hiding in the barn with a wound in his side. Before he slips away he teaches you how to stand.','是一个藏在谷仓里、腰上带伤的饿汉。他临走前教了你怎么扎马步。'),c:'gold',fx:{skill:4,align:3}}]},
  {l:T('Leave it to the grown-ups','交给大人'),out:[{w:2,t:T('They set a trap and catch the neighbour’s cat. Nobody is happy.','他们下了夹子，夹住了邻居家的猫。谁都不高兴。'),c:'muted'},{w:1,t:T('The hens stop vanishing. Nobody ever finds out why.','鸡不再丢了。没人知道是为什么。'),c:'muted'}]}]});

I({id:'l2_dryvoices',age:[5,11],once:1,text:()=>T('Playing near the old dry well, you hear a voice coming up from the bottom.','你在那口废弃的枯井边玩，听见井底传来人声。'),
 opts:[{l:T('Lower the bucket rope','把吊桶绳放下去'),out:[{w:2,t:T('A tinker climbs out, furious and grateful. He fell in two days ago. He mends every pot in your house for free.','一个补锅匠爬了上来，又气又感激。他前天掉进去了。他把你家的锅全补了，一文没收。'),c:'good',fx:{align:4,happy:4}},
   {w:1,t:T('Nobody climbs out. The rope is cut clean when you pull it up.','没有人爬上来。你把绳子拉上来，断口齐整整的。'),c:'muted',fx:{happy:-3}},
   {w:1,t:T('A wounded woman climbs out, says "You never saw me," and is gone before you can blink.','一个受伤的女子爬了上来，说"你没见过我"，一眨眼就不见了。'),fx:{qi:2,flag:'l2_wellwoman'}}]},
  {l:T('Run and tell the adults','跑去叫大人'),out:[{w:2,t:T('It is an echo from the cellar next door, where the neighbours count their hidden silver. Now the whole village knows.','原来是隔壁地窖里的回声，邻居在数藏起来的银子。这下全村都知道了。'),fx:{smarts:2}},
   {w:1,t:T('The constables pull out a thief who has been hiding there for a week. You get a copper reward.','捕快从井里揪出一个躲了一个星期的贼。你得了一文赏钱。'),c:'good',fx:{money:1,fame:1}}]}]});

I({id:'l2_escortflags',age:[5,12],cd:5,ctx:s=>{const c=scene();c.npc=npc(s,{occ:8,age:rint(30,50)});return c},text:c=>T(`An escort convoy rolls through the village, flags snapping. The chief guard, ${c.npc.en}, stops to water the horses.`,`一队镖车穿村而过，镖旗猎猎作响。镖头${c.npc.zh}停下来饮马。`),
 out:[{w:2,t:c=>T(`${c.npc.en} lets you hold the spear. It is much heavier than it looks. You decide you will carry one someday.`,`${c.npc.zh}让你摸了摸那杆长枪。比看上去沉多了。你暗暗发誓，将来也要扛一杆。`),c:'good',fx:{happy:5,skill:1}},
  {w:1,t:T('You count the carts and the guards and tell the chief that one guard keeps looking at the hills. He thanks you, oddly seriously.','你数了数车和镖师，告诉镖头有个镖师老往山上看。他很郑重地谢了你。'),c:'good',fx:{smarts:3,fame:1}},
  {w:1,t:T('A horse steps on your foot. The chief gives you a copper and a lecture about horses.','一匹马踩了你的脚。镖头给了你一文钱，外加一通关于马的教训。'),c:'muted',fx:{money:1,hurt:[1,4],cause:T('a horse’s hoof','马蹄')}}]});

I({id:'l2_recitation',age:[6,12],cd:4,text:()=>T('The tutor announces a test: recite the Thousand Character Classic, start to finish, tomorrow.','先生宣布明天要考试：把《千字文》从头背到尾。'),
 opts:[{l:T('Study all night','通宵背书'),out:[{w:s=>1+s.smarts/25,t:T('Not a single slip. The tutor raises an eyebrow, which from him is a parade.','一字不差。先生挑了挑眉毛——对他来说，这已经是大大的嘉奖了。'),c:'good',fx:{smarts:4}},{w:2,t:T('You fall asleep at character six hundred and dream the rest.','背到第六百字时你睡着了，剩下的都是梦里背的。'),c:'muted',fx:{smarts:1}}]},
  {l:T('Fake a stomach ache','装肚子疼'),out:[{w:2,t:T('Your mother doses you with bitter herbs for three days. Honesty would have been easier.','母亲给你灌了三天苦药。早知道还不如老实背书。'),fx:{happy:-3}},{w:1,t:T('It works. You feel clever and slightly hollow.','成了。你觉得自己很聪明，又有点空落落的。'),fx:{align:-1,happy:2}}]},
  {l:T('Write it on your palm','写在手心上'),out:[{w:1,t:T('It is a hot day. Your palm sweats the words into a blue smear.','那天很热。手心的汗把字晕成了一团蓝。'),c:'bad',fx:{happy:-3}},{w:1,t:T('You pass. The tutor knows, and says nothing, and you know he knows.','你过了。先生知道，没说破，你也知道他知道。'),c:'muted',fx:{smarts:1}}]}]});

I({id:'l2_mudfort',age:[6,12],once:1,text:()=>T('The village children split into two "sects" and build mud forts on either side of the ditch. You are elected sect leader.','村里的孩子分成两个"门派"，在水沟两边各筑了一座泥巴堡垒。你被推举为掌门。'),
 opts:[{l:T('Lead the charge','率众冲锋'),fight:FG(PW(1,2),'spar',T('The war of the mud forts','泥堡之战'),T('a mud fight','泥巴大战'),()=>T('the rival sect leader','对面的"掌门"')),
   win:[{t:T('You plant a bamboo flag on their fort. For one summer you rule the ditch.','你把竹竿旗插上了对方的泥堡。整个夏天，这条水沟归你管。'),c:'good',fx:{fame:1,happy:6}}],
   lose:[{t:T('You are captured and made to eat a mud dumpling. Diplomacy follows.','你被俘了，被迫吃了一个泥丸子。随后两派开始和谈。'),fx:{happy:-1}}]},
  {l:T('Propose a peace treaty','提议和谈'),out:[{w:2,t:T('You draft a treaty on a roof tile. Both sides sign. It holds until dinner.','你在一片瓦上写了和约，两边都画了押。一直管用到晚饭时分。'),c:'good',fx:{smarts:3,align:2}},{w:1,t:T('Your own side calls you a traitor and elects someone louder.','自己人骂你是叛徒，另选了一个嗓门更大的当掌门。'),c:'muted',fx:{happy:-3}}]},
  {l:T('Secretly defect','偷偷投敌'),out:[{t:T('You are welcomed as a hero, then trusted by nobody. A useful lesson about the jianghu.','你被当成英雄迎了过去，然后谁也不信你了。这是关于江湖很有用的一课。'),c:'muted',fx:{smarts:2,align:-2}}]}]});

I({id:'l2_haystack',age:[6,12],once:1,text:()=>T('You and your friends roast sweet potatoes behind the haystack. The haystack catches fire.','你和伙伴们躲在草垛后面烤红薯。草垛着火了。'),
 opts:[{l:T('Fight the fire','扑火'),out:[{w:2,t:T('You beat it out with your jacket. The jacket does not survive. The sweet potatoes are perfect.','你用外衣把火扑灭了。衣服没了，红薯烤得正好。'),c:'good',fx:{happy:3,align:2}},{w:1,t:T('Half the haystack is gone. You confess and spend the autumn rebuilding it.','草垛烧了一半。你认了错，一整个秋天都在重新堆草垛。'),c:'muted',fx:{skill:1,align:3}}]},
  {l:T('Run','跑'),out:[{w:2,t:T('Everybody knows anyway. It is a very small village.','反正大家都知道了。村子就这么小。'),c:'bad',fx:{happy:-4,align:-2}},{w:1,t:T('A neighbour puts it out and never tells. Years later he winks at you at your wedding.','一个邻居把火扑灭了，从没说出去。多年后他在你的喜宴上冲你眨了眨眼。'),fx:{happy:2}}]}]});

I({id:'l2_beggarsong',age:[5,12],once:1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:7,age:s.age+rint(0,3)});return c},text:c=>T(`A beggar child, ${c.npc.en}, teaches you a silly counting song with strange words in it.`,`一个叫${c.npc.zh}的小乞丐教你唱一首数数的歌谣，里面有些古怪的词。`),
 out:[{w:2,t:T('You sing it in the market. Three beggars stop dead, stare at you, and then bow. It was a Beggar Sect password.','你在集市上唱了起来。三个乞丐愣住了，盯着你看，然后躬身行礼。原来那是丐帮的暗号。'),c:'gold',fx:{fame:1,flag:'l2_beggarsong',meet:'friend',bond:65}},
  {w:2,t:c=>T(`You sing it for weeks. ${c.npc.en} becomes your best friend until the beggars move on in spring.`,`你唱了好几个星期。${c.npc.zh}成了你最好的朋友，直到开春乞丐们走了。`),fx:{happy:5,meet:'friend',bond:72}},
  {w:1,t:T('Your mother hears it and washes your mouth out with soap. It was a rude song.','母亲听见了，用皂角给你洗了嘴。那是首骂人的歌。'),c:'muted',fx:{happy:-1}}]});

I({id:'l2_marketduel',age:[5,12],cd:8,text:()=>T('Two swordsmen fight in the market square. You watch the whole thing from under a vegetable cart.','两个剑客在集市上动起手来。你趴在菜车底下看完了全程。'),
 opts:[{l:T('Copy the moves at home','回家照着比划'),out:[{w:2,t:T('You break a stool and learn one real thing about footwork.','你踢坏了一张板凳，也真学到了一点步法。'),fx:{skill:2}},{w:1,t:T('Your father watches, frowns, and corrects your elbow. He has never told you he used to fight.','父亲看着，皱皱眉，纠正了你的手肘。他从没说过自己以前练过武。'),c:'gold',fx:{skill:4}}]},
  {l:T('Pick up the dropped sword tassel','捡起掉落的剑穗'),out:[{w:1,t:T('The winner comes back for it and gives you a silver bead for keeping it clean.','赢的那个回来找剑穗，因为你保管得干净，赏了你一颗银珠子。'),c:'good',fx:{money:5}},{w:1,t:T('The loser comes back for it. He is not gracious about it.','输的那个回来找。他可没那么客气。'),c:'muted',fx:{happy:-2}},{w:1,t:T('Nobody comes back for it. You keep it all your life.','谁也没回来找。你把它留了一辈子。'),fx:{happy:3}}]}]});

I({id:'l2_dawnteacher',age:[6,12],once:1,text:()=>T('You discover the gentle village teacher practising with a sword in the bamboo grove before dawn.','你发现村里那位斯文的教书先生天不亮就在竹林里练剑。'),
 opts:[{l:T('Ask him to teach you','求他教你'),out:[{w:2,t:T('He agrees, on condition you never tell. Every dawn for a year. Then one morning he is gone, leaving his books to you.','他答应了，条件是你永远不许说出去。整整一年，每天拂晓。有一天早上他走了，把书都留给了你。'),c:'gold',fx:{skill:5,smarts:3,happy:-2}},{w:1,t:T('He says swords bring nothing but grief, and teaches you calligraphy instead. Somehow your wrist gets stronger.','他说刀剑只会带来伤心事，改教你写字。不知怎的，你的手腕变得有力了。'),fx:{smarts:4,skill:1}}]},
  {l:T('Keep his secret','替他保密'),out:[{w:2,t:T('He notices you noticed. From then on he slips you the hardest books.','他知道你看见了。从那以后，他总塞给你最难的书。'),c:'good',fx:{smarts:4}},{w:1,t:T('Men with blades come asking about him one autumn. You say nothing. He leaves that night.','一年秋天，几个带刀的人来打听他。你什么也没说。他当夜就走了。'),c:'muted',fx:{align:4}}]},
  {l:T('Tell everyone','告诉所有人'),out:[{t:T('The village is thrilled. The teacher is not. He moves to another county within the month.','全村人都很兴奋，先生却不。不到一个月，他就搬去别的县了。'),c:'bad',fx:{happy:-2,fame:1}}]}]});

/* ================= teenage years (13–17) ================= */
I({id:'l2_lovenotes',age:[13,17],once:1,ctx:s=>{const c=scene();c.npc=npc(s,{sex:s.gender==='m'?'f':'m',age:s.age+rint(-1,1)});return c},text:c=>T(`Your best friend asks you to carry love letters to ${c.npc.en}. After the fourth letter you realise you are in love with ${c.npc.him} yourself.`,`你最好的朋友托你给${c.npc.zh}送情书。送到第四封，你发现自己也喜欢上${c.npc.ta}了。`),
 opts:[{l:T('Deliver them faithfully','老老实实地送'),out:[{w:2,t:T('They marry two years later. You are the guest who drinks the most.','两年后他们成了亲。喜宴上你喝得最多。'),c:'muted',fx:{align:3,happy:-4}},{w:1,t:c=>T(`${c.npc.en} reads the letters, then looks at you. "Did you write these?" You didn’t. ${c.npc.He} looks disappointed.`,`${c.npc.zh}读完信，抬头看你："这是你写的吗？"不是。${c.npc.ta}看上去有点失望。`),fx:{happy:2}}]},
  {l:T('Slip in a letter of your own','偷偷夹一封自己的'),out:[{w:1,t:T('It is answered, not your friend’s. Your friend does not speak to you for a year.','回信是给你的，不是给你朋友的。朋友一年没理你。'),c:'good',fx:{meet:'lover',bond:60,happy:6,align:-2}},{w:1,t:T('Both letters come back with the spelling corrected.','两封信都被退了回来，错别字还被改了。'),c:'muted',fx:{smarts:1,happy:-2}}]},
  {l:T('Tell your friend the truth','对朋友说实话'),out:[{w:1,t:T('Your friend laughs, then hugs you. "Let them choose." Neither of you is chosen.','朋友笑了，又抱了抱你："让人家自己挑吧。"结果谁都没被挑上。'),fx:{happy:3}},{w:1,t:T('You fight in the rain, then make up in the rain. It is all very dramatic.','你们在雨里打了一架，又在雨里和好了。一切都很有戏剧性。'),fx:{happy:2,skill:1}}]}]});

I({id:'l2_betrothal',age:[14,17],once:1,w:1.5,when:s=>!living(s,['lover','spouse']).length,ctx:s=>{const c=scene();c.npc=npc(s,{sex:s.gender==='m'?'f':'m',age:s.age+rint(-1,3),occ:s.gender==='m'?12:11});return c},text:c=>T(`Your parents announce a betrothal: you will marry ${c.npc.en}, whom you have never met, in three years.`,`爹娘宣布给你订了亲：三年后你要和一个素未谋面的人成亲——${c.npc.zh}。`),
 opts:[{l:T('Obey','听从'),out:[{w:1,t:T('The other family breaks it off a year later. You are oddly offended.','一年后对方家里退了亲。你竟然有点不服气。'),c:'muted',fx:{happy:-2}},{w:1,t:T('The families fall out over the dowry. The match is off. You are free, and slightly sad.','两家为了彩礼闹翻了，婚事告吹。你自由了，又有点失落。'),c:'muted'}]},
  {l:T('Refuse loudly','大闹一场，坚决不从'),out:[{w:2,t:T('Weeks of shouting. In the end your mother takes your side, which surprises everyone, especially your father.','吵了好几个星期。最后母亲站在了你这边，所有人都很意外，尤其是父亲。'),fx:{happy:3}},{w:1,t:T('You are locked in your room for a month. You read every book in it twice.','你被关在屋里一个月。屋里的书你都读了两遍。'),fx:{smarts:4,happy:-4}}]},
  {l:T('Sneak a look at them first','先偷偷去看一眼'),out:[{w:2,t:c=>T(`You climb their garden wall and fall at ${c.npc.en}’s feet. ${c.npc.He} laughs until ${c.npc.he} cries. Perhaps this will be all right.`,`你翻墙进了人家的花园，正好摔在${c.npc.zh}脚下。${c.npc.ta}笑得眼泪都出来了。也许这门亲事也不坏。`),c:'good',fx:{meet:'lover',bond:60,happy:6}},{w:1,t:c=>T(`${c.npc.en} is beating a servant. You go home and refuse.`,`你看见${c.npc.zh}在打下人。你回家就退了亲。`),c:'muted',fx:{align:2}}]}]});

I({id:'l2_riddletip',age:[13,17],once:1,when:s=>!s.sect,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([13,14,1]),age:rint(30,60)});return c},text:c=>T(`Your first paid work: carrying dishes at an inn. A guest, ${c.npc.en}, leaves a heavy tip and a riddle written on the table in wine.`,`你第一份工钱是在客栈端盘子。一位客人${c.npc.zh}留下一大笔赏钱，还用酒在桌上写了一个谜语。`),
 opts:[{l:T('Solve the riddle','解谜'),out:[{w:s=>1+s.smarts/30,t:T('The answer is a place and a day. You go. The guest is waiting, and gives you a lesson in breathing and a hard look at your future.','谜底是一个地方和一个日子。你去了。那位客人在等你，教了你一套吐纳法，又意味深长地看了看你。'),c:'gold',fx:{qi:6,smarts:2}},{w:2,t:T('You puzzle over it until the wine dries. The answer was "wine".','你琢磨到酒干了。谜底是"酒"。'),c:'muted',fx:{smarts:1}}]},
  {l:T('Pocket the tip and wipe the table','收下赏钱，擦桌子'),out:[{w:2,t:T('Eight coppers. Your first wages. You buy your mother a comb.','八文钱。你的第一笔工钱。你给母亲买了一把梳子。'),c:'good',fx:{money:8,happy:4}},{w:1,t:T('The innkeeper takes half. Welcome to work.','掌柜抽走了一半。欢迎来到干活的世界。'),c:'muted',fx:{money:4}}]}]});

I({id:'l2_tofubully',age:[13,17],cd:5,ctx:s=>{const c=scene();c.npc=npc(s,{occ:21,age:s.age+2,lv:Math.max(3,Math.round(power(s)*.95+rint(2,6)))});return c},text:c=>T(`${c.npc.en} and two older boys are squeezing the old tofu seller for "protection money".`,`${c.npc.zh}带着两个大孩子，在向卖豆腐的老婆婆收"保护费"。`),
 opts:[{l:T('Step in','出手'),fight:FG((s,c)=>c.npc.lv,'light',T('For the tofu seller','为卖豆腐的出头'),T('a scuffle with bullies','和恶少斗殴')),
   win:[{t:T('They run. The tofu seller gives you free tofu for the rest of her life, which is a lot of tofu.','他们跑了。卖豆腐的老婆婆从此一辈子白送你豆腐，那可是很多豆腐。'),c:'good',fx:{align:5,fame:2,happy:4}}],
   lose:[{t:T('They beat you, but word gets round, and they never come back to that street.','你挨了一顿揍，但事情传开了，他们再也没来过那条街。'),c:'muted',fx:{align:4}}]},
  {l:T('Fetch the constable','去叫捕快'),out:[{w:1,t:T('The constable turns out to be the ringleader’s uncle.','原来捕快是那个领头的亲舅舅。'),c:'muted',fx:{smarts:2}},{w:1,t:T('The constable clips their ears. The bullies know who fetched him.','捕快揪了他们的耳朵。恶少们知道是谁叫来的。'),fx:{align:2,enemy:1}}]},
  {l:T('Pay them off yourself','自己掏钱打发'),out:[{t:T('They take your coppers and come back next week for more.','他们拿了你的铜板，下个星期又来要了。'),c:'bad',fx:{money:-5,align:1}}]}]});

I({id:'l2_peachoath',age:[13,17],once:1,ctx:s=>{const c=scene();c.npc=npc(s,{age:s.age+rint(-1,1),sex:s.gender});return c},text:c=>T(`You, ${c.npc.en} and another friend climb into an orchard at night to swear brotherhood like the heroes in the stories.`,`你、${c.npc.zh}和另一个朋友半夜翻进果园，学故事里的英雄结拜。`),
 out:[{w:3,t:c=>T(`You burn incense, kneel, and vow to die on the same day. The farmer chases you out. ${c.npc.en} is your sworn sibling from that night on.`,`你们烧了香，跪下，发誓同年同月同日死。果园主人把你们撵了出去。从那夜起，${c.npc.zh}就是你的结义兄弟了。`),c:'good',fx:{meet:'sworn',bond:75,happy:6}},
  {w:1,t:T('The third friend backs out halfway through the oath. You finish it as a pair, a little embarrassed.','第三个朋友誓言念到一半就打了退堂鼓。你们俩有点尴尬地把誓词念完了。'),fx:{meet:'sworn',bond:65,happy:3}},
  {w:1,t:T('You cut your fingers for the blood oath. It gets infected. The brotherhood survives; the finger barely does.','你们割破手指歃血为盟。伤口发了炎。兄弟情还在，手指差点没保住。'),fx:{meet:'sworn',bond:70,hurt:[4,10],cause:T('an infected blood oath','歃血的伤口发炎')}}]});

I({id:'l2_runjianghu',age:[14,17],once:1,w:1.5,when:s=>!s.sect,text:()=>T('You pack a bundle — a knife, two flatbreads, a borrowed book of martial tales — and set off before dawn to find a sect that will take you.','你收拾了一个包袱——一把刀、两张烙饼、一本借来的武侠话本——天不亮就出了门，去找肯收你的门派。'),
 out:[{w:2,t:T('You reach a mountain gate. A bored disciple tells you to come back with a recommendation. You walk home in the rain.','你走到了一座山门前。一个无精打采的弟子让你拿推荐信再来。你冒雨走回了家。'),c:'muted',fx:{happy:-3,skill:1}},
  {w:1,t:T('Bandits take the flatbreads, the knife and the book. They give back the book, saying it is "very unrealistic".','山贼抢走了烙饼、刀和书。书又还给了你，说"写得太假了"。'),c:'muted',fx:{happy:-2,smarts:1}},
  {w:1,t:T('You fall in with a travelling herbalist, walk three provinces, and come home brown, thin and much wiser.','你跟着一个游方郎中走了三个省，回家时又黑又瘦，懂事多了。'),c:'good',fx:{smarts:4,maxHealth:2,happy:3}},
  {w:1,t:T('Your father catches up with you at the first crossroads. He doesn’t shout. He just walks you home, and that is worse.','父亲在第一个岔路口追上了你。他没骂你，只是陪你走回了家。那比挨骂还难受。'),fx:{happy:-1,align:1}}]});

I({id:'l2_tattoo',age:[14,17],once:1,text:()=>T('A tattooist in the night market offers to ink you cheap. Your friends are all watching.','夜市上一个刺青师傅说给你便宜刺一个。朋友们都在旁边看着。'),
 opts:[{l:T('A tiger on the back','背上刺一只老虎'),out:[{w:1,t:T('It is a magnificent tiger. Your mother sees it and cries for a day.','好一只威风的老虎。母亲看见了，哭了一整天。'),fx:{looks:2,happy:3}},{w:1,t:T('His hand slips. It looks like a cat. A worried cat.','师傅手一抖，刺得像只猫。一只发愁的猫。'),c:'muted',fx:{happy:-2}}]},
  {l:T('A plum blossom on the wrist','手腕上刺一朵梅花'),out:[{t:T('Small and fine. Years later, strangers in the jianghu will ask if you are from the Plum Blossom school.','小巧精致。多年后，江湖上总有人问你是不是梅花派的。'),c:'good',fx:{looks:2}}]},
  {l:T('Back out','临阵退缩'),out:[{w:2,t:T('Your friends tease you for a week. Your skin thanks you for a lifetime.','朋友们笑话了你一个星期。你的皮肤会感谢你一辈子。'),c:'muted'},{w:1,t:T('Your friend gets the tiger instead. It goes septic. You feel very wise.','你朋友替你刺了那只老虎，结果化脓了。你觉得自己特别明智。'),fx:{smarts:1}}]}]});

I({id:'l2_oldconstable',age:[13,17],cd:5,ctx:s=>{const c=scene();c.npc=npc(s,{age:s.age,lv:Math.max(3,Math.round(power(s)*1.0+rint(1,5)))});return c},text:c=>T(`A retired constable teaches staff fighting to the street’s youngsters for free. His favourite is ${c.npc.en}, who smirks at you.`,`一位退休的老捕快免费教街坊少年耍棍。他最得意的徒弟${c.npc.zh}冲你冷笑。`),
 opts:[{l:T('Challenge the favourite','挑战得意门生'),fight:FG((s,c)=>c.npc.lv,'spar',T('Staff practice','棍棒切磋'),T('a staff bout','棍棒切磋')),
   win:[{t:c=>T(`The old constable laughs and gives you ${c.npc.en}’s place at the front. ${c.npc.en} becomes your rival for years.`,`老捕快哈哈大笑，让你站到了${c.npc.zh}原来的位置。${c.npc.zh}从此跟你较劲了好多年。`),c:'good',fx:{skill:3,meet:'rival',bond:40}}],
   lose:[{t:c=>T(`${c.npc.en} helps you up. "Again tomorrow?" You become friends.`,`${c.npc.zh}把你拉起来："明天再来？"你们成了朋友。`),fx:{skill:2,meet:'friend',bond:60}}]},
  {l:T('Practise alone at the back','在后排自己练'),out:[{w:2,t:T('Slow and steady. By winter your staff hums when it turns.','慢慢来。到了冬天，你的棍子一转就呼呼生风。'),fx:{skill:3}},{w:1,t:T('The old man notices you and quietly shows you his own trick for disarming a blade.','老头注意到了你，悄悄教了你一手空手夺刀的绝活。'),c:'gold',fx:{skill:5}}]}]});

I({id:'l2_firstdice',age:[13,17],once:1,text:()=>T('Older boys invite you to a dice game in the alley behind the butcher’s.','几个大孩子叫你去肉铺后巷掷骰子。'),
 opts:[{l:T('Bet a few coppers','押几文钱'),out:[{w:1,t:T('You win twelve coppers and feel invincible. This is a dangerous feeling.','你赢了十二文，觉得自己天下无敌。这种感觉很危险。'),fx:{money:12,happy:4}},{w:1,t:T('You lose five coppers and the feeling of being clever.','你输了五文钱，也输掉了自以为聪明的感觉。'),c:'muted',fx:{money:-5,smarts:1}}]},
  {l:T('Bet everything','全押上'),out:[{w:1,t:T('You lose your savings in three throws. You never touch dice again.','三把就输光了积蓄。你从此再也不碰骰子。'),c:'bad',fx:{money:-30,happy:-6,smarts:2}},{w:1,t:T('You win big. The older boys decide you must be cheating and take it back.','你赢了一大笔。大孩子们认定你出千，又全抢了回去。'),c:'muted',fx:{hurt:[3,8],cause:T('an alley dice game','后巷赌局')}}]},
  {l:T('Watch the dice instead','只看骰子不下注'),out:[{t:T('You notice one die lands on six too often. Knowing that feels better than winning.','你发现有一颗骰子老是出六点。看穿这个比赢钱还痛快。'),c:'good',fx:{smarts:3}}]}]});

I({id:'l2_burnedtales',age:[13,17],once:1,when:s=>s.smarts>=30,text:()=>T('Your father finds the wuxia tales hidden under your mattress and burns them in the stove.','父亲在你褥子底下翻出了武侠话本，扔进灶里烧了。'),
 opts:[{l:T('Write your own','自己写一部'),out:[{w:2,t:T('You fill three notebooks with a swordsman who is suspiciously like you. Your friends pass it round in secret.','你写满了三个本子，主角是个和你可疑地相像的剑客。朋友们偷偷传着看。'),c:'good',fx:{smarts:4,happy:4}},{w:1,t:T('A bookseller buys it for 20 taels. It sells well in two counties under a fake name.','一个书商花二十两买了去，换了个笔名，在两个县卖得很好。'),c:'gold',fx:{smarts:4,money:20,fame:2}}]},
  {l:T('Sulk, then sneak out to the storyteller','赌气，然后溜去听说书'),out:[{w:2,t:T('The storyteller lets you sit by the stage for free if you sweep up after.','说书先生说，只要你散场后扫地，就让你坐在台边白听。'),fx:{happy:4,smarts:1}},{w:1,t:T('Your father is already there, in the back row, pretending not to see you.','父亲已经坐在后排了，装作没看见你。'),c:'good',fx:{happy:6}}]}]});

I({id:'l2_spilledsecret',age:[13,17],once:1,text:()=>T('Your best friend tells the whole town who you secretly like.','你最好的朋友把你暗恋谁的事告诉了全镇。'),
 opts:[{l:T('Forgive them','原谅'),out:[{w:2,t:T('They are miserable with guilt. You make them carry your water for a month and call it even.','对方内疚得不行。你让对方替你挑了一个月水，就算两清了。'),c:'good',fx:{align:2,happy:2}},{w:1,t:T('The person you like hears the rumour and comes to ask if it is true.','你喜欢的人听到了风声，跑来问你是不是真的。'),c:'gold',fx:{happy:7}}]},
  {l:T('Get revenge with a prank','恶作剧报复'),out:[{w:2,t:T('You fill their shoes with frogs. Honour is satisfied, and so are the frogs.','你在对方鞋里塞满了青蛙。仇报了，青蛙也很满意。'),fx:{happy:4}},{w:1,t:T('The prank goes too far. Their father comes round. Your father is not amused.','玩笑开过了头。对方的爹找上门来。你爹一点也笑不出来。'),c:'bad',fx:{happy:-4,align:-2}}]},
  {l:T('Cut them off','绝交'),out:[{t:T('You never speak again. At thirty you will barely remember why.','你们再也没说过话。到三十岁时，你都快想不起是为什么了。'),c:'muted',fx:{happy:-3}}]}]});

I({id:'l2_maskedlantern',age:[14,17],cd:4,ctx:s=>{const c=scene();c.npc=npc(s,{sex:s.gender==='m'?'f':'m',age:s.age+rint(-1,2)});return c},text:()=>T('At the Lantern Festival a stranger in a fox mask takes your hand and pulls you through the crowd to watch the fireworks.','元宵灯会上，一个戴狐狸面具的人拉起你的手，穿过人群去看烟火。'),
 opts:[{l:T('Lift the mask','揭开面具'),out:[{w:2,t:c=>T(`It is ${c.npc.en}, who you have walked past every day for years without noticing.`,`原来是${c.npc.zh}。这些年你天天从${c.npc.ta}身边走过，竟从没留意过。`),c:'good',fx:{meet:'lover',bond:55,happy:6}},{w:1,t:T('It is your cousin, playing a joke. You will never live it down.','是你表亲，在跟你开玩笑。这事你一辈子都别想翻篇了。'),c:'muted',fx:{happy:-2}}]},
  {l:T('Leave the mystery','不去揭开'),out:[{w:2,t:T('When the fireworks end, the hand lets go. You look for a fox mask at every festival for ten years.','烟火散了，那只手也松开了。此后十年，每逢灯会你都在找一张狐狸面具。'),c:'muted',fx:{happy:3}},{w:1,t:T('A fox mask is left on your doorstep the next morning, with a single plum blossom.','第二天早上，你家门口放着那张狐狸面具，还有一枝梅花。'),c:'good',fx:{happy:5}}]}]});

/* ================= marriage and family ================= */
I({id:'l2_spousetrain',age:[20,70],cd:12,when:s=>!!spouseOf(s)&&power(s)>=20,ctx:L2spCtx,text:c=>T(`${c.p.n.py} announces ${L2he(c.p)} wants to learn to fight, and that you are going to teach ${L2him(c.p)}.`,`${c.p.n.cn}宣布要学武，而且要你来教。`),
 opts:[{l:T('Teach patiently','耐心地教'),out:[{w:2,t:c=>T(`Every evening in the courtyard. ${c.p.n.py} is terrible, then less terrible. It is the happiest year of your marriage.`,`每天傍晚在院子里练。${c.p.n.cn}起先一塌糊涂，后来好了一点。那是你们婚后最快活的一年。`),c:'good',fx:{bond:12,happy:6}},{w:1,t:c=>T(`${c.p.n.py} turns out to be gifted, and annoyingly so. By winter ${L2he(c.p)} disarms you twice.`,`${c.p.n.cn}竟然很有天分，天分高得叫人生气。入冬时，${L2ta(c.p)}已经把你的兵器打落了两回。`),c:'gold',fx:{bond:15,happy:4,f:(s,c)=>{const p=person(s,c.p.id);if(p)p.lv+=15}}}]},
  {l:T('Refuse','拒绝'),out:[{w:1,t:T('"Fine." It is not fine. Dinner is cold for a month.','"好吧。"其实不好。一个月的饭都是冷的。'),c:'bad',fx:{bond:-8}},{w:1,t:c=>T(`${c.p.n.py} finds a different teacher. A handsome one. You change your mind.`,`${c.p.n.cn}另找了个师父，长得还挺俊。你改主意了。`),fx:{bond:3,happy:-2}}]},
  {l:T('Teach, but go easy','教，但手下留情'),out:[{t:c=>T(`${c.p.n.py} notices immediately and is insulted. You start again, properly.`,`${c.p.n.cn}一下子就看出来了，觉得受了轻视。你只好重新认真教。`),fx:{bond:5,skill:1}}]}]});

I({id:'l2_motherinlaw',age:[20,70],once:1,when:s=>!!spouseOf(s),ctx:L2spCtx,text:c=>T(`${c.p.n.py}’s widowed mother moves into your house "for a little while".`,`${c.p.n.cn}守寡的母亲搬进了你家，说是"住一阵子"。`),
 opts:[{l:T('Win her over','讨她欢心'),out:[{w:2,t:T('You learn her favourite dishes and her favourite grievances. By winter she defends you to the neighbours.','你学会了她爱吃的菜，也记住了她爱念叨的委屈。到了冬天，她在邻居面前都替你说话。'),c:'good',fx:{bond:8,happy:3}},{w:1,t:T('She teaches you an old family recipe for wound salve. It works better than anything in the shops.','她教了你一个祖传的金疮药方子，比铺子里卖的都灵。'),c:'gold',fx:{item:'salve',heal:20,bond:5}}]},
  {l:T('Endure in silence','默默忍着'),out:[{w:2,t:T('She stays four years. You become very good at silence.','她一住就是四年。你练成了一身沉默的功夫。'),c:'muted',fx:{happy:-5,qi:3}},{w:1,t:T('She leaves after a year, and to your surprise you miss her cooking.','她住了一年就走了。没想到你竟有点想念她做的菜。'),fx:{happy:2}}]},
  {l:T('Ask her to leave','请她搬走'),out:[{w:1,t:T('She leaves. Your spouse doesn’t forgive you for a long time.','她走了。你的另一半很久都没原谅你。'),c:'bad',fx:{bond:-15}},{w:1,t:T('She laughs. "Finally, someone with a spine." She stays, and respects you.','她笑了："总算有个有骨气的。"她留了下来，还对你另眼相看。'),fx:{bond:3,happy:2}}]}]});

I({id:'l2_kidsword',age:[22,75],cd:6,w:4,when:s=>L2kid(s,4,13).length>0,ctx:L2kidCtx(4,13),text:c=>T(`Your ${L2sk(c.k).en} ${c.k.n.py} took your sword down from the wall and has cut the neighbour’s washing line, two lanterns and a goat’s rope.`,`你的${L2sk(c.k).zh}${c.k.n.cn}把墙上的剑取了下来，砍断了邻居的晾衣绳、两盏灯笼和一根拴羊的绳子。`),
 opts:[{l:T('Punish them','责罚'),out:[{w:2,t:T('Kneeling in the courtyard until dark. The sword stays on a higher hook now.','罚跪院子直到天黑。剑现在挂到更高的钩子上了。'),c:'muted',fx:{bond:-4}},{w:1,t:T('They cry, you cry, and the neighbour’s goat is never found.','孩子哭了，你也哭了，邻居家的羊再也没找回来。'),fx:{money:-8,bond:-2}}]},
  {l:T('Teach them properly','好好教'),out:[{w:2,t:c=>T(`Wooden sword first. ${c.k.n.py} practises every morning without being told. You pretend not to be proud.`,`先从木剑练起。${c.k.n.cn}每天早上不用催就去练。你装作一点也不得意。`),c:'good',fx:{bond:10,f:(s,c)=>{const p=person(s,c.k.id);if(p)p.lv+=4}}},{w:1,t:T('Their first lesson is apologising to the neighbour. Their second is paying for the goat.','第一课是给邻居赔礼，第二课是赔那只羊。'),fx:{bond:5,money:-8,align:2}}]},
  {l:T('Laugh','哈哈大笑'),out:[{t:T('Your spouse does not laugh. The neighbour does not laugh. The goat, wherever it is, may be laughing.','另一半没笑，邻居也没笑。那只羊，不管跑到哪儿去了，大概在笑。'),c:'muted',fx:{bond:6,happy:3,money:-8}}]}]});

I({id:'l2_childsuitor',age:[34,95],cd:10,w:2,when:s=>L2kid(s,17,32).length>0,ctx:s=>{const k=pick(L2kid(s,17,32));const c={k,who:k.id};c.npc=npc(s,{sex:k.sex==='m'?'f':'m',age:k.age+rint(-2,3),lv:Math.max(3,Math.round(power(s)*.8+rint(0,6)))});return c},text:c=>T(`Your ${L2sk(c.k).en} ${c.k.n.py} wants to marry ${c.npc.en}, ${c.npc.desc.en}.`,`你的${L2sk(c.k).zh}${c.k.n.cn}要和${c.npc.zh}成亲，对方是个${c.npc.desc.zh}。`),
 opts:[{l:T('Give your blessing','点头答应'),out:[{w:3,t:T('A small, loud, happy wedding. You dance, badly.','一场小小的、热热闹闹的喜事。你跳了舞，跳得很难看。'),c:'good',fx:{happy:8,bond:10,money:-30}},{w:1,t:T('Five years later they are still happy. You were right, for once.','五年后他们依然恩爱。你总算对了一回。'),c:'good',fx:{happy:6,bond:8}}]},
  {l:T('Test the suitor with a spar','跟对方过几招试试'),fight:FG((s,c)=>c.npc.lv,'spar',T('Testing the in-law','考校新人'),T('a spar with a future in-law','与未来亲家切磋')),
   win:[{w:2,t:c=>T(`${c.npc.en} loses gracefully and asks for pointers. You approve.`,`${c.npc.zh}输得很有风度，还向你讨教。你点头了。`),c:'good',fx:{happy:5,bond:4}},{w:1,t:c=>T(`${c.npc.en} sulks. ${c.k.n.py} marries ${c.npc.him} anyway.`,`${c.npc.zh}输了就耍脾气。${c.k.n.cn}还是和${c.npc.ta}成了亲。`),c:'muted',fx:{bond:-4}}],
   lose:[{t:c=>T(`${c.npc.en} beats you, then bows and helps you up. You give your blessing with a bruised dignity.`,`${c.npc.zh}赢了你，然后鞠躬把你扶起来。你带着一点挂彩的面子点了头。`),c:'good',fx:{happy:3,bond:6}}]},
  {l:T('Forbid it','不许'),out:[{w:2,t:c=>T(`${c.k.n.py} elopes. A letter arrives a year later, with a baby’s footprint in ink.`,`${c.k.n.cn}跟人私奔了。一年后来了一封信，上面按着一个婴儿的墨脚印。`),c:'bad',fx:{bond:-25,happy:-6}},{w:1,t:c=>T(`${c.k.n.py} obeys, and never quite looks at you the same way.`,`${c.k.n.cn}听了你的话，但看你的眼神再也不一样了。`),c:'muted',fx:{bond:-15}}]}]});

I({id:'l2_oldletters',age:[25,80],cd:15,when:s=>!!spouseOf(s),ctx:L2spCtx,text:c=>T(`Clearing out a chest, you find a bundle of letters ${c.p.n.py} has kept hidden for years.`,`收拾箱子时，你发现了一叠${c.p.n.cn}藏了多年的信。`),
 opts:[{l:T('Read them','拆开看'),out:[{w:1,t:c=>T(`They are love letters, to ${c.p.n.py}, from you, from the first year. Every single one.`,`是情书——你写给${c.p.n.cn}的，从头一年起，一封不落。`),c:'good',fx:{happy:6,bond:6}},
   {w:1,t:c=>T(`They are from ${c.p.n.py}’s old sect. ${c.p.n.py} was once a disciple, and ran away, and never told you. You understand a few old scars now.`,`是${c.p.n.cn}从前门派的来信。${L2ta(c.p)}曾是某派弟子，后来逃了出来，从没对你说过。你终于明白${L2ta(c.p)}身上那几道旧伤是怎么回事了。`),fx:{smarts:2,bond:4,f:(s,c)=>{const p=person(s,c.p.id);if(p)p.lv+=20}}},
   {w:1,t:T('They are from an old love. Nothing happened. Something almost did. You spend a long night deciding that "almost" is allowed.','是一个旧情人写的。什么也没发生，只是差一点。你想了一整夜，决定"差一点"是可以原谅的。'),c:'muted',fx:{happy:-4,bond:-3}}]},
  {l:T('Put them back unread','原封不动地放回去'),out:[{w:2,t:T('Some doors are better left closed. You sleep well.','有些门还是关着好。你睡得很香。'),c:'muted',fx:{qi:2}},{w:1,t:c=>T(`${c.p.n.py} notices the chest was moved, and that the letters were not. Something warm passes between you.`,`${c.p.n.cn}发现箱子动过，信却没动。你们之间多了一份暖意。`),c:'good',fx:{bond:10}}]}]});

I({id:'l2_spouseill',age:[25,90],cd:10,when:s=>!!spouseOf(s),ctx:L2spCtx,text:c=>T(`${c.p.n.py} has a cough that will not go away. The doctor’s face is careful.`,`${c.p.n.cn}咳嗽一直不好。大夫的脸色很谨慎。`),
 opts:[{l:T('Pay for the best physician (100 taels)','请最好的大夫（一百两）'),cost:100,out:[{w:3,t:T('Weeks of bitter medicine, and then one morning the cough is gone.','苦药喝了好几个星期，终于有一天早上不咳了。'),c:'good',fx:{bond:10,happy:5}},{w:1,t:T('The physician is a fraud. The cough clears on its own anyway, which he takes credit for.','那大夫是个骗子。咳嗽自己好了，他却把功劳揽了过去。'),c:'muted',fx:{bond:6}}]},
  {l:T('Nurse them yourself','亲自照料'),out:[{w:2,t:T('You learn to make congee properly at last. It gets better, slowly.','你终于学会了熬一锅像样的粥。病慢慢好了。'),c:'good',fx:{bond:14,happy:2}},{w:1,t:T('It gets worse before it gets better. You do not sleep for a month.','病先重了，然后才好起来。你一个月没睡好觉。'),fx:{bond:12,hurt:[3,8],cause:T('exhaustion','劳累过度')}}]},
  {l:T('Climb the mountain for a rare herb','上山采一味珍稀草药'),out:[{w:2,t:T('You find it on a cliff edge and come home with torn hands. It works.','你在悬崖边采到了，回家时手都磨破了。药很灵。'),c:'good',fx:{bond:15,hurt:[4,12],cause:T('a cliff edge','悬崖')}},{w:1,t:T('You come back empty-handed. The cough has cleared while you were gone. You laugh for the first time in weeks.','你空手而归。没想到你不在的时候咳嗽自己好了。你几个星期来第一次笑了。'),fx:{bond:8,happy:4}}]}]});

I({id:'l2_childexam',age:[30,85],cd:8,w:2.5,when:s=>L2kid(s,15,30).length>0,ctx:L2kidCtx(15,30),text:c=>T(`Your ${L2sk(c.k).en} ${c.k.n.py} is sitting the county examination.`,`你的${L2sk(c.k).zh}${c.k.n.cn}要去参加县试了。`),
 opts:[{l:T('Hire a tutor (80 taels)','请个先生（八十两）'),cost:80,out:[{w:2,t:c=>T(`${c.k.n.py} passes high on the list. The whole lane sets off firecrackers.`,`${c.k.n.cn}高中榜上。整条巷子都放了鞭炮。`),c:'gold',fx:{happy:10,fame:3,bond:6}},{w:1,t:T('They fail, but the tutor says they write the best poems he has ever marked.','没考上，但先生说那是他判过的最好的诗。'),c:'muted',fx:{happy:2,bond:4}}]},
  {l:T('Let them find their own way','由孩子自己去'),out:[{w:1,t:T('They pass, just. They are prouder of it than any tutor could have made them.','勉强考过了。孩子为此骄傲得很，比请先生考上还骄傲。'),c:'good',fx:{happy:6,bond:5}},{w:2,t:T('They fail and announce they want to open a noodle shop instead. It is a very good noodle shop.','没考上，孩子宣布要去开面馆。那面馆开得很不错。'),fx:{happy:3,money:[5,30]}}]},
  {l:T('Bribe the examiner (200 taels)','贿赂考官（二百两）'),cost:200,out:[{w:2,t:T('They pass. They never learn why. You never forget.','考过了。孩子永远不知道为什么，你永远忘不了。'),c:'muted',fx:{align:-6,fame:2}},{w:1,t:T('The examiner is arrested for taking bribes. Your name is in his ledger.','考官因受贿被抓了，账本上有你的名字。'),c:'bad',fx:{align:-6,wanted:1,bond:-10}}]}]});

I({id:'l2_childjianghu',age:[32,95],cd:10,w:2,when:s=>L2kid(s,15,28).length>0,ctx:L2kidCtx(15,28),text:c=>T(`Your ${L2sk(c.k).en} ${c.k.n.py} has packed a bundle. ${c.k.sex==='m'?'He':'She'} wants to go out into the jianghu, the way you once did.`,`你的${L2sk(c.k).zh}${c.k.n.cn}收拾好了包袱，要像你当年一样闯荡江湖。`),
 opts:[{l:T('Give them your old weapon and your blessing','把旧兵器和祝福一起给孩子'),out:[{w:2,t:T('Letters come, every few months, full of adventures they are clearly toning down for you.','每隔几个月来一封信，里面的历险，明显是怕你担心才往轻里写的。'),c:'good',fx:{bond:15,happy:4,f:(s,c)=>{const p=person(s,c.k.id);if(p)p.lv+=10}}},{w:1,t:T('They come back in a year with a scar, a horse and a sweetheart. In that order of importance, apparently.','一年后孩子回来了，带着一道疤、一匹马和一个心上人。按重要程度排，显然就是这个顺序。'),c:'good',fx:{bond:10,happy:8}}]},
  {l:T('Forbid it','不许去'),out:[{w:1,t:T('They go anyway, through the window. You leave money on the sill.','孩子还是从窗户跑了。你在窗台上留了银子。'),c:'muted',fx:{bond:-5,money:-20}},{w:1,t:T('They stay, and run the family business better than you ever did. Sometimes you catch them staring at the road.','孩子留了下来，把家业打理得比你还好。只是你偶尔会看见他望着那条路发呆。'),fx:{bond:-6,money:[20,60]}}]},
  {l:T('Go with them for the first month','陪着走头一个月'),out:[{t:T('You are the most embarrassing companion in the jianghu, and also the most useful. They admit it only years later.','你是江湖上最让人丢脸的同伴，也是最管用的。孩子过了很多年才肯承认。'),c:'good',fx:{bond:12,happy:6,skill:1}}]}]});

I({id:'l2_inheritfight',age:[40,100],cd:12,w:5,when:s=>living(s,'child').filter(p=>p.age>=12).length>=2,ctx:s=>{const ks=shuffle(living(s,'child').filter(p=>p.age>=12));return{a:ks[0],b:ks[1]}},text:c=>T(`${c.a.n.py} and ${c.b.n.py}, your children, are quarrelling loudly about who will get what when you are gone. You are in the next room.`,`你的两个孩子${c.a.n.cn}和${c.b.n.cn}正为将来的家产吵得不可开交。你就在隔壁屋里。`),
 opts:[{l:T('Walk in and clear your throat','走进去咳嗽一声'),out:[{w:2,t:T('Silence. Then both of them try to hug you at once.','一片寂静。然后两个人同时扑过来抱你。'),fx:{happy:2}},{w:1,t:T('They are mortified. The quarrel ends and is never mentioned again.','他们羞得无地自容。争吵就此结束，再也没提过。'),c:'good',fx:{happy:4,f:(s,c)=>{addBond(person(s,c.a.id),4);addBond(person(s,c.b.id),4)}}}]},
  {l:T('Spend it all now','现在就把钱花光'),out:[{t:T('You buy a fine horse, a feast for the whole street and a very good coffin. Your children stop quarrelling about money; there isn’t any.','你买了一匹好马，请整条街吃了一顿，还订了一口上好的棺材。孩子们不再为钱吵了——因为没钱了。'),c:'gold',fx:{f:s=>{s.money=Math.round(s.money*.3)},happy:12,fame:2}}]},
  {l:T('Write a fair will tonight','当晚就立下公道的遗嘱'),out:[{w:2,t:T('Split evenly, with a line for each of them that you hope they will read twice.','家产平分，给每人各写了一句话，你希望他们能读两遍。'),c:'good',fx:{smarts:1,happy:3}},{w:1,t:T('They both think it unfair. That is how you know it is fair.','两个人都觉得不公平。你就知道这下公平了。'),c:'muted',fx:{happy:1}}]}]});

I({id:'l2_teahousekid',age:[24,80],cd:8,w:3,when:s=>L2kid(s,6,15).length>0,ctx:L2kidCtx(6,15),text:c=>T(`The teahouse owner sends a message: your ${L2sk(c.k).en} ${c.k.n.py} has been telling stories about you to paying customers. Wildly exaggerated stories.`,`茶馆掌柜捎话来：你的${L2sk(c.k).zh}${c.k.n.cn}在茶馆里给客人讲你的故事，还收钱。讲得天花乱坠。`),
 opts:[{l:T('Go and listen secretly','偷偷去听'),out:[{w:2,t:T('In this version you killed a dragon with a chopstick. The crowd loves it. So, quietly, do you.','这一版里，你用一根筷子宰了一条龙。客人们听得如痴如醉。你也偷偷地爱听。'),c:'good',fx:{happy:6,fame:1,bond:5}},{w:1,t:T('In this version you are sad and lonely and very brave. It is closer to the truth than you’d like.','这一版里，你孤独、伤心、又很勇敢。比你愿意承认的更接近真相。'),c:'muted',fx:{happy:2,bond:8}}]},
  {l:T('Demand a cut','要分成'),out:[{t:T('Negotiations are tough. You settle for a third and a promise to make you taller in the next telling.','谈判很艰难。最后你分三成，外加下回讲的时候把你说高一点。'),fx:{money:[3,15],happy:4,bond:4}}]},
  {l:T('Put a stop to it','叫停'),out:[{t:T('They stop. The teahouse is quieter. You miss the dragon.','孩子不讲了。茶馆冷清了。你有点想念那条龙。'),c:'muted',fx:{bond:-5}}]}]});

/* ================= money and property ================= */
I({id:'l2_hauntedtavern',age:[20,95],cd:12,when:s=>L2has(s,'tavern')||L2has(s,'teastall'),text:()=>T('Customers whisper that your place is haunted: a cup moves on its own, and someone weeps in the storeroom at midnight.','客人们私下说你的店闹鬼：杯子会自己挪动，半夜库房里有人哭。'),
 opts:[{l:T('Hire a Daoist exorcist (30 taels)','请道士驱邪（三十两）'),cost:30,out:[{w:2,t:T('Much bell-ringing. The weeping stops. The exorcist eats for free for a month.','一通摇铃作法。哭声停了。道士在你店里白吃了一个月。'),fx:{happy:2}},{w:1,t:T('The exorcist runs out screaming. Business triples from curious visitors.','道士尖叫着跑了出来。好奇的客人一下子多了三倍。'),c:'gold',fx:{money:[60,150]}}]},
  {l:T('Sit up and watch','亲自守夜'),out:[{w:2,t:T('It is a runaway servant girl living in the storeroom. You give her a job.','原来是个逃出来的丫鬟躲在库房里。你给了她一份差事。'),c:'good',fx:{align:6,meet:'acq',bond:65}},{w:1,t:T('It is a stray cat and the wind. You feel foolish, then relieved, then hungry.','是一只野猫和风声。你先觉得自己可笑，然后松了口气，然后饿了。'),c:'muted'},{w:1,t:T('It is not a cat. You do not talk about that night, ever.','那不是猫。那一夜的事，你一辈子都没再提。'),c:'muted',fx:{qi:4,happy:-4}}]},
  {l:T('Advertise it','借势招揽'),out:[{t:T('"The Haunted House: Ghost Wine, Half Price at Midnight." It is a sensation.','"鬼屋：子时鬼酒半价。"一下子轰动全城。'),c:'good',fx:{money:[40,120],fame:1}}]}]});

I({id:'l2_tenant',age:[20,95],cd:10,when:s=>L2has(s,'courtyard')||L2has(s,'mansion')||L2has(s,'manor'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([1,27,25,17]),age:rint(25,60)});return c},text:c=>T(`You rent out a spare room to ${c.npc.en}, ${c.npc.desc.en}. Three months in, ${c.npc.he} cannot pay.`,`你把一间空屋租给了${c.npc.zh}，一个${c.npc.desc.zh}。住了三个月，${c.npc.ta}交不起租了。`),
 opts:[{l:T('Let it go','算了'),out:[{w:2,t:c=>T(`${c.npc.en} pays you back in work: the roof stops leaking, the gate stops squeaking.`,`${c.npc.zh}拿干活抵租：屋顶不漏了，门也不吱呀响了。`),c:'good',fx:{align:3,happy:3}},{w:1,t:c=>T(`Years later ${c.npc.en} becomes rich and sends you ten times the rent with a very long letter.`,`多年后${c.npc.zh}发了财，给你寄来十倍的房租，外加一封长长的信。`),c:'gold',fx:{align:3,money:[60,200],meet:'friend',bond:70}}]},
  {l:T('Throw them out','赶出去'),out:[{w:2,t:T('They leave at night. Your pots leave with them.','对方连夜走了，顺走了你家的锅。'),c:'bad',fx:{money:-10,align:-2}},{w:1,t:T('They curse your house on the way out. Everything goes slightly wrong for a year.','对方临走前咒了你家。那一年诸事不顺。'),c:'muted',fx:{happy:-4,align:-2}}]},
  {l:T('Ask what they can do','问问对方会什么'),out:[{w:1,t:T('They can read accounts. They find the steward has been robbing you for years.','对方会看账。查出你的管家多年来一直在贪你的钱。'),c:'good',fx:{money:[40,120],smarts:2}},{w:1,t:T('They can cook. You eat better than ever and stop asking about rent.','对方会做饭。你从没吃得这么好过，也就不再提房租了。'),fx:{happy:5}}]}]});

I({id:'l2_rivalstall',age:[16,95],cd:10,when:s=>owned(s,'biz').length>0,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([26,17,5]),age:rint(25,55)});return c},text:c=>T(`${c.npc.en} opens a business right across the street from yours, with lower prices and a louder sign.`,`${c.npc.zh}在你店对面开了一家，价钱更低，招牌更响。`),
 opts:[{l:T('Cut your prices','降价'),out:[{w:1,t:T('A price war. Both of you lose money. Customers have never been happier.','打起了价格战。两家都亏钱，客人们从没这么高兴过。'),c:'muted',fx:{money:[-80,-20]}},{w:1,t:T('They run out of money first and sell you their stock cheap.','对方先撑不住了，把存货便宜卖给了你。'),c:'good',fx:{money:[20,80]}}]},
  {l:T('Propose a partnership','提议合伙'),out:[{w:2,t:c=>T(`You and ${c.npc.en} split the street: they do the morning trade, you the evening. Both of you get rich, slowly.`,`你和${c.npc.zh}分了这条街：对方做早市，你做晚市。两家都慢慢发了财。`),c:'good',fx:{money:[40,120],meet:'friend',bond:55}},{w:1,t:c=>T(`${c.npc.en} agrees, then steals your best cook.`,`${c.npc.zh}嘴上答应，转头就挖走了你最好的厨子。`),c:'bad',fx:{money:-30}}]},
  {l:T('Lean on them with some muscle','找几个人去"说说"'),out:[{w:1,t:T('They close within a week. People on the street look at you differently now.','对方一个星期就关了门。街坊们看你的眼神变了。'),c:'muted',fx:{align:-6,money:[20,60]}},{w:1,t:T('Their brother is a constable.','对方的兄弟是个捕快。'),c:'bad',fx:{align:-4,wanted:1,money:-40}}]}]});

I({id:'l2_silkventure',age:[22,85],cd:12,when:s=>s.money>=300,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([5,23,17]),age:rint(30,60)});return c},text:c=>T(`${c.npc.en}, ${c.npc.desc.en}, wants 200 taels to fund a boatload of silk going down the Grand Canal. "Double your money by autumn."`,`${c.npc.desc.zh}${c.npc.zh}想找你出二百两，合伙运一船丝绸走大运河。"入秋就翻一番。"`),
 opts:[{l:T('Invest 200 taels','投二百两'),cost:200,out:[{w:2,t:T('The boat arrives. You get back 420 taels and a bolt of very good silk.','船到了。你拿回四百二十两，外加一匹上好的丝绸。'),c:'gold',fx:{money:420,happy:5}},{w:1,t:T('The boat sinks in a storm. Your partner weeps real tears. You get nothing.','船在风浪里沉了。合伙人哭得真心实意。你血本无归。'),c:'bad',fx:{happy:-6}},{w:1,t:c=>T(`There never was a boat. ${c.npc.en} has left town.`,`根本就没有什么船。${c.npc.zh}已经跑了。`),c:'bad',fx:{happy:-8,smarts:2,enemy:1}},{w:1,t:T('The silk is held up by customs for a year, then sells at a modest profit.','丝绸在关卡被扣了一年，最后卖了个小赚。'),c:'muted',fx:{money:250}}]},
  {l:T('Ask to see the boat first','先要看看船'),out:[{w:1,t:T('There is a boat. It is very small. You invest 50 taels instead and make 40.','船倒是有，就是很小。你只投了五十两，赚了四十两。'),c:'good',fx:{money:40,smarts:2}},{w:1,t:c=>T(`${c.npc.en} suddenly remembers an urgent appointment elsewhere.`,`${c.npc.zh}忽然想起别处还有急事。`),c:'muted',fx:{smarts:2}}]},
  {l:T('Decline','婉拒'),out:[{t:T('You hear later that it went... somehow. Nobody will say how.','后来你听说那趟买卖……怎么样了。谁也说不清。'),c:'muted'}]}]});

I({id:'l2_warehousefire',age:[20,95],cd:15,when:s=>owned(s,'biz').length>0||owned(s,'house').length>0,text:()=>T('Fire breaks out in the building next to yours in the middle of the night.','半夜，隔壁的房子着了火。'),
 opts:[{l:T('Fight the fire with the neighbours','和邻居一起救火'),out:[{w:2,t:T('A bucket line until dawn. Your place is saved, and the whole street owes you a drink.','排成一列传水桶，一直救到天亮。你的家业保住了，整条街都欠你一顿酒。'),c:'good',fx:{align:4,fame:1,hurt:[2,8],cause:T('a fire','火灾')}},{w:1,t:T('You pull a child out of the smoke. The child’s father is the magistrate’s clerk; your taxes are mysteriously lower for years.','你从浓烟里抱出一个孩子。孩子的爹是县衙的书吏；此后好几年，你的税莫名其妙地少了。'),c:'gold',fx:{align:6,fame:3,money:[30,80],hurt:[5,12],cause:T('a fire','火灾')}}]},
  {l:T('Save your own valuables first','先抢自己的值钱东西'),out:[{w:2,t:T('You save your strongbox. The street saves your building. Nobody quite forgives you.','你抢出了钱箱。街坊们救下了你的房子。大家心里都不太原谅你。'),c:'muted',fx:{align:-3}},{w:1,t:T('The wind changes. You lose the building but keep the box.','风向变了。房子没了，钱箱保住了。'),c:'bad',fx:{money:[-150,-60],happy:-6}}]},
  {l:T('Pay the fire brigade extra (40 taels)','多给救火会银子（四十两）'),cost:40,out:[{t:T('They work very hard on your side of the street, and not much on the other.','他们在你这边拼了命，对面那边就没怎么管。'),c:'muted',fx:{align:-2}}]}]});

I({id:'l2_nightthief',age:[20,95],cd:10,when:s=>s.money>=400,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([7,28,13]),age:rint(18,45),lv:Math.max(3,Math.round(power(s)*.85+rint(0,8)))});return c},text:()=>T('You wake to a soft sound: someone is lifting the lid of your strongbox.','你被一声轻响惊醒：有人在掀你的钱箱盖子。'),
 opts:[{l:T('Leap out of bed','跳下床'),fight:FG((s,c)=>c.npc.lv,'light',T('The night thief','夜贼'),T('a night thief','夜贼')),
   win:[{w:2,t:c=>T(`You pin ${c.npc.en} to the floor. ${c.npc.He} is half-starved. You must decide what to do with ${c.npc.him} in the morning; you give ${c.npc.him} breakfast first.`,`你把${c.npc.zh}按在地上。${c.npc.ta}饿得只剩半条命。早上该怎么处置，你先给${c.npc.ta}吃了顿早饭再说。`),c:'good',fx:{align:4,meet:'acq',bond:45}},{w:1,t:T('You catch the thief and hand them to the yamen. The reward is small; the story is good.','你抓住了贼，送去了衙门。赏钱不多，故事却好听。'),c:'good',fx:{fame:2,money:10}}],
   lose:[{t:T('The thief knocks you down and leaves with a fistful of silver.','贼把你撂倒了，抓了一把银子就跑。'),c:'bad',fx:{money:[-150,-40]}}]},
  {l:T('Shout for the household','大声喊人'),out:[{w:2,t:T('The thief flees empty-handed over the wall.','贼两手空空翻墙跑了。'),c:'good'},{w:1,t:T('The thief flees, with the box. Your household arrives in time to admire the empty spot.','贼抱着箱子跑了。家里人赶到时，正好欣赏那块空地。'),c:'bad',fx:{money:[-200,-60]}}]},
  {l:T('Pretend to sleep and watch','装睡偷看'),out:[{w:1,t:T('The thief takes only a little, bows to your sleeping form and leaves. You find it oddly touching.','贼只拿了一点点，还冲"熟睡"的你鞠了一躬才走。你竟然有点感动。'),c:'muted',fx:{money:[-30,-10]}},{w:1,t:T('The thief is your own nephew. You say nothing, ever, and move the box.','贼是你自己的侄子。你什么也没说，从此把钱箱挪了地方。'),c:'muted',fx:{smarts:2,money:-20}}]}]});

I({id:'l2_buriedjar',age:[20,95],once:1,when:s=>owned(s,'house').length>0,text:()=>T('Digging a new flower bed, your spade hits a sealed jar full of old coins.','挖新花坛时，你的铁锹碰到一只封着口的瓦罐，里面装满了古钱。'),
 opts:[{l:T('Keep it quietly','悄悄留下'),out:[{w:2,t:T('Old coins from a fallen dynasty. A collector pays well and asks no questions.','是前朝的古钱。一个收藏家出了好价钱，什么也没问。'),c:'good',fx:{money:[80,250]}},{w:1,t:T('Under the coins is a note: "For my grandson. Forgive me." You never find the grandson, and it bothers you.','钱底下有张字条："留给我孙儿。原谅我。"你一直没找到那个孙子，心里总是放不下。'),c:'muted',fx:{money:[60,150],happy:-3}}]},
  {l:T('Report it to the magistrate','报官'),out:[{w:1,t:T('The magistrate keeps it all "for the treasury". He buys a new sedan chair the next week.','县太爷说要"充公"，全收了去。下个星期他换了一顶新轿子。'),c:'muted',fx:{align:3,smarts:1}},{w:1,t:T('The magistrate is honest, astonishingly, and gives you a third.','县太爷竟然是个清官，分了你三成。'),c:'good',fx:{align:4,money:[30,80],fame:1}}]},
  {l:T('Find the old owner’s family','寻找原主人家'),out:[{t:T('It takes a year of asking. An old woman weeps over the jar and gives you her husband’s sword.','打听了一年。一个老婆婆抱着瓦罐哭了，把她亡夫的佩剑送给了你。'),c:'gold',fx:{align:8,item:'steelsword',fame:2}}]}]});

I({id:'l2_coffinescort',age:[20,90],cd:12,w:1.5,when:s=>L2has(s,'escortco')||L2has(s,'tavern')||s.money>=800,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([31,5,11]),age:rint(30,60)});return c},text:c=>T(`${c.npc.en} offers 600 taels for a single job: carry a sealed coffin to the capital, and never open it.`,`${c.npc.zh}出价六百两，只办一件事：把一口封死的棺材送到京城，路上绝不能打开。`),
 opts:[{l:T('Take the job','接下'),out:[{w:2,t:T('Three weeks on the road. The coffin is heavier on some days than others. You deliver it, take the silver, and do not ask.','路上走了三个星期。那口棺材有时重有时轻。你送到了，收了银子，什么也没问。'),c:'gold',fx:{money:600,happy:-2}},
   {w:1,t:T('On the tenth night the coffin knocks from inside. You open it. A prince climbs out, very grateful and very wanted.','第十天夜里，棺材里头有人敲。你打开一看，爬出来一位落难王爷，感激涕零，也被通缉得很厉害。'),c:'gold',fx:{money:300,fame:5,wanted:1,deed:T('Smuggled a fugitive prince out in a coffin','用棺材偷运落难王爷')}},
   {w:1,t:T('Bandits ambush the convoy for the coffin. You drive them off, but lose your fee to repairs and doctors.','山贼劫道，就冲那口棺材来的。你打退了他们，可酬金全赔在修车和请大夫上了。'),c:'bad',fx:{hurt:[10,25],cause:T('bandits after a coffin','劫棺的山贼'),fame:2}}]},
  {l:T('Open it before deciding','先开棺再说'),out:[{w:1,t:T('Silver ingots, packed in salt. Someone is avoiding taxes. You charge double.','是用盐码好的银锭。有人在逃税。你要了双倍的价钱。'),c:'good',fx:{money:500,align:-4}},{w:1,t:T('A body, and a letter that names the murderer. You take it to the magistrate instead.','是一具尸首，还有一封写明凶手的信。你转手交给了县衙。'),c:'good',fx:{align:8,fame:4,enemy:1}}]},
  {l:T('Refuse','不接'),out:[{t:T('A rival takes the job. You hear his agency closes six months later. Nobody says why.','对头接了这单。半年后你听说他的镖局关了门。没人说为什么。'),c:'muted'}]}]});

/* ================= old age (55+) ================= */
I({id:'l2_lastduel',age:[58,95],once:1,when:s=>power(s)>=25,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:s.age+rint(-3,4),lv:Math.max(5,Math.round(power(s)*(.85+R()*.25)))});return c},text:c=>T(`A letter from ${c.npc.en}, a rival from forty years ago: "We are both old. One last bout, before one of us forgets how."`,`四十年前的老对头${c.npc.zh}来信："咱们都老了。趁还没忘了怎么出手，再比最后一场。"`),
 opts:[{l:T('Accept','应战'),fight:FG((s,c)=>c.npc.lv,'light',T('One last bout','最后一战'),T('a duel between two old rivals','两个老对头的决斗')),
   win:[{w:2,t:c=>T(`You win, and both of you sit down in the dust afterwards, too tired to stand. ${c.npc.en} laughs until ${c.npc.he} wheezes.`,`你赢了。之后两个人都坐在地上，累得站不起来。${c.npc.zh}笑得直喘。`),c:'good',fx:{fame:4,happy:8,meet:'friend',bond:70}},{w:1,t:T('You win. On the way home you realise you will miss hating them.','你赢了。回家路上你才发现，以后没人可恨了，竟有点寂寞。'),c:'muted',fx:{fame:3,happy:2}}],
   lose:[{t:c=>T(`${c.npc.en} wins, then insists on paying for dinner. You let ${c.npc.him}, out of spite.`,`${c.npc.zh}赢了，又非要请客吃饭。你偏让${c.npc.ta}请，算是报复。`),fx:{happy:4,meet:'friend',bond:60}}]},
  {l:T('Reply: “Let’s drink instead.”','回信："不如喝酒。"'),out:[{w:2,t:T('You get drunk and argue about who would have won. Both of you claim victory.','你们喝醉了，争论当年到底谁会赢。两人都说是自己。'),c:'good',fx:{happy:8,meet:'friend',bond:65}},{w:1,t:T('Your reply arrives a week after the funeral.','你的回信到时，对方已经下葬一个星期了。'),c:'muted',fx:{happy:-8}}]}]});

I({id:'l2_grandstory',age:[50,100],cd:5,w:2,when:s=>living(s,'child').some(p=>p.age>=20),text:()=>T('Your grandchild climbs into your lap and demands a story about when you were young.','孙辈爬到你膝上，非要听你年轻时的故事。'),
 opts:[{l:T('Tell the truth','讲真事'),out:[{w:2,t:T('The truth is less exciting and more sad. The child listens to every word and then asks a question that makes you cry.','真事没那么精彩，倒有些伤感。孩子一字不落地听完，问了一个让你落泪的问题。'),c:'good',fx:{happy:6,smarts:1}},{w:1,t:T('The child falls asleep halfway. You keep telling it anyway, to the ceiling.','孩子听到一半就睡着了。你还是对着房梁讲完了。'),c:'muted',fx:{happy:3}}]},
  {l:T('Embellish wildly','添油加醋'),out:[{w:2,t:T('By the end you defeated ninety bandits with a fish. The child tells the whole village.','讲到最后，你用一条鱼打败了九十个山贼。孩子讲给了全村听。'),c:'good',fx:{fame:1,happy:6}},{w:1,t:T('Your spouse, overhearing, corrects every detail from the doorway.','老伴在门口听见了，把每个细节都纠正了一遍。'),fx:{happy:4}}]},
  {l:T('Teach them a stance instead','教孩子一个架势'),if:s=>power(s)>=15,out:[{t:T('Small knees, wobbling. Then, suddenly, still. You see yourself, sixty years ago.','小腿还在打颤，忽然就稳住了。你仿佛看见了六十年前的自己。'),c:'gold',fx:{happy:8,qi:2}}]}]});

I({id:'l2_forgetful',age:[65,110],cd:10,text:()=>T('You walk into a room and cannot remember why. It happens more and more.','你走进一间屋，却想不起来要干什么。这种事越来越多了。'),
 opts:[{l:T('Practise your forms every morning','每天早上练一遍套路'),out:[{w:2,t:T('Your hands remember what your head forgets. That helps.','脑子忘了的，手还记得。这很有帮助。'),c:'good',fx:{qi:2,smarts:1}},{w:1,t:T('You do the same form twice and wonder why your legs ache.','同一套拳打了两遍，还纳闷腿怎么这么酸。'),c:'muted',fx:{skill:1}}]},
  {l:T('Write everything down','什么都记下来'),out:[{w:2,t:T('Notes everywhere. One says only "DO NOT TRUST THE DUCK." You have no idea.','到处都是字条。有一张只写着"别信那只鸭子"。你完全想不起是什么意思。'),fx:{happy:3}},{w:1,t:T('Your notes become an accidental memoir. Your grandchildren read them aloud for years.','这些字条不知不觉成了一部回忆录。孙辈们念了好多年。'),c:'good',fx:{happy:5,fame:1}}]},
  {l:T('Laugh it off','一笑了之'),out:[{t:T('You find your spectacles on your head, again. You laugh. It is not the worst way to grow old.','眼镜又在头顶上找到了。你笑了。这样老去，也不算太坏。'),c:'muted',fx:{happy:2}}]}]});

I({id:'l2_oldenemy',age:[55,100],once:1,when:s=>s.people.some(p=>p.alive&&['enemy','rival'].includes(p.rel)),ctx:s=>{const p=pick(s.people.filter(p=>p.alive&&['enemy','rival'].includes(p.rel)));return{p,who:p.id}},text:c=>T(`${c.p.n.py}, your old ${c.p.rel==='enemy'?'enemy':'rival'}, comes to your gate leaning on a stick. "I am dying. I didn’t want to do it still hating you."`,`你的老${c.p.rel==='enemy'?'仇家':'对头'}${c.p.n.cn}拄着拐杖来到你门前。"我快死了。不想带着恨走。"`),
 opts:[{l:T('Forgive','原谅'),out:[{w:2,t:T('You talk until the lamp burns out. In the morning, for the first time in decades, neither of you is angry.','你们一直谈到灯油烧尽。第二天早上，几十年来头一回，谁心里都没有怨气了。'),c:'good',fx:{happy:10,align:5,f:(s,c)=>{const p=person(s,c.p.id);if(p){p.rel='friend';p.bond=60}}}},{w:1,t:T('You forgive. They recover entirely. Now you have a friend you don’t know what to do with.','你原谅了。结果对方的病全好了。你多了个不知该怎么相处的朋友。'),fx:{happy:5,align:4,f:(s,c)=>{const p=person(s,c.p.id);if(p){p.rel='friend';p.bond=45}}}}]},
  {l:T('Refuse','拒绝'),out:[{w:1,t:T('They nod, as if they expected it, and limp away. You do not sleep that night.','对方点点头，像是早料到了，一瘸一拐地走了。那一夜你没睡着。'),c:'muted',fx:{happy:-5}},{w:1,t:T('"Good," they say. "I would have been disappointed." They grin. You almost grin back.','"好，"对方说，"你要是原谅了，我倒失望了。"对方咧嘴一笑。你也差点笑了。'),fx:{happy:2}}]},
  {l:T('Ask why it all began','问当年究竟为何结仇'),out:[{w:1,t:T('Neither of you can remember. That is the saddest and funniest thing you have heard in years.','两个人谁都想不起来了。这是你这些年听过的最可悲也最好笑的事。'),c:'good',fx:{happy:6,smarts:2,f:(s,c)=>{const p=person(s,c.p.id);if(p){p.rel='acq';p.bond=50}}}},{w:1,t:T('They tell you. It was your fault. You had forgotten. You apologise, forty years late.','对方说了。是你的错，你早忘了。你道了歉，晚了四十年。'),fx:{align:6,happy:3,f:(s,c)=>{const p=person(s,c.p.id);if(p){p.rel='acq';p.bond=55}}}}]}]});

I({id:'l2_owncoffin',age:[60,110],once:1,when:s=>s.money>=30,text:()=>T('You decide to buy your own coffin, and to try it out first.','你决定给自己买口棺材，而且要先躺进去试试。'),
 opts:[{l:T('The fine cypress one (60 taels)','上好的柏木棺材（六十两）'),cost:60,out:[{w:2,t:T('Roomy, fragrant, very comfortable. You fall asleep in it. The carpenter’s apprentice faints when you sit up.','宽敞、清香、舒服得很。你在里面睡着了。你坐起来的时候，木匠的徒弟当场吓晕了。'),c:'good',fx:{happy:6}},{w:1,t:T('You store it in the hall and use it as a table for twenty years. Guests find this upsetting.','你把它放在堂屋，当了二十年的桌子。客人们都很不自在。'),fx:{happy:4,lifespan:1}}]},
  {l:T('The plain pine one (10 taels)','普通的松木棺材（十两）'),cost:10,out:[{t:T('"It’s only for lying in," you tell the carpenter. He is disappointed in you.','"反正就是躺着的。"你对木匠说。他对你很失望。'),c:'muted',fx:{happy:2}}]},
  {l:T('Decide you won’t be needing one yet','决定还用不着'),out:[{w:2,t:T('You walk home briskly. The carpenter watches you go, measuring.','你健步如飞地走回家。木匠目送着你，眼睛还在量尺寸。'),fx:{happy:3}},{w:1,t:T('You take up a morning walk out of pure stubbornness.','你纯粹出于赌气，养成了晨走的习惯。'),c:'good',fx:{maxHealth:2,happy:2}}]}]});

I({id:'l2_secondspring',age:[55,90],once:1,when:s=>!spouseOf(s)&&!living(s,'lover').length,ctx:s=>{const c=scene();c.npc=npc(s,{sex:s.gender==='m'?'f':'m',age:s.age+rint(-6,4),occ:s.gender==='m'?27:19});return c},text:c=>T(`${c.npc.en}, who lives alone at the end of the lane, keeps finding reasons to borrow your salt.`,`住在巷子尽头、独自过活的${c.npc.zh}，总找借口来借你家的盐。`),
 opts:[{l:T('Invite them to dinner','请对方来吃饭'),out:[{w:2,t:c=>T(`Dinner becomes every dinner. At your age, you skip the long courtship. ${c.npc.en} moves in by spring.`,`一顿饭变成了顿顿饭。到了这把年纪，用不着慢慢磨。开春时，${c.npc.zh}就搬了过来。`),c:'gold',fx:{happy:12,lifespan:1,f:(s,c)=>{const p=storeNpc(s,c,'spouse',75);if(p)s.deeds.push(T(`Married ${p.n.py} late in life`,`晚年与${p.n.cn}结为夫妻`))}}},{w:1,t:T('A pleasant evening. You both agree you are too set in your ways, and borrow salt for years.','一个愉快的夜晚。你们都承认自己太倔，然后接着互相借了好多年盐。'),c:'good',fx:{happy:5,meet:'friend',bond:70}}]},
  {l:T('Just lend the salt','只借盐'),out:[{w:2,t:T('A great deal of salt changes hands. The lane is very amused.','两家之间来来回回借了好多盐。整条巷子都看得乐呵呵的。'),c:'muted',fx:{happy:2}},{w:1,t:T('One day they stop coming. You go and knock. They were only sick; they recover, and the salt resumes.','有一天对方不来了。你去敲门，原来只是病了。病好了，借盐也接着来了。'),fx:{happy:3,meet:'friend',bond:60}}]},
  {l:T('Your children object','孩子们反对'),if:s=>living(s,'child').length>0,out:[{t:T('You listen politely to their objections, then do whatever you like. It is very freeing.','你客客气气地听完孩子们的意见，然后爱干什么干什么。真是痛快。'),c:'good',fx:{happy:6,meet:'lover',bond:70}}]}]});

I({id:'l2_heir',age:[60,100],once:1,when:s=>power(s)>=40||owned(s,'biz').length>0,text:s=>T('It is time to choose who will carry on what you built.','该选个人来接你这一摊了。'),
 opts:[{l:T('Your own child','自己的孩子'),if:s=>living(s,'child').some(p=>p.age>=16),out:[{w:2,t:T('They accept, solemnly, and spend the next year asking you how to do everything.','孩子郑重地接了下来，接下来一年事事都来问你。'),c:'good',fx:{happy:6,f:s=>living(s,'child').forEach(p=>addBond(p,6))}},{w:1,t:T('They accept, and quietly change everything you did. It works better. You are proud and annoyed.','孩子接了，然后悄悄把你的规矩全改了。效果更好。你既骄傲又不服气。'),fx:{happy:3,smarts:1}}]},
  {l:T('Your best disciple or friend','最得意的徒弟或朋友'),if:s=>living(s,['disciple','friend','sworn']).length>0,out:[{w:2,t:T('Your family grumbles. Your chosen heir weeps. Ten years from now, everyone will say you chose well.','家里人有怨言，接班的人哭了。十年后，大家都会说你选对了人。'),c:'good',fx:{fame:3,happy:4}},{w:1,t:T('They decline: "I only wanted to learn from you, not become you."','对方婉拒了："我只想跟你学，不想变成你。"'),c:'muted',fx:{happy:-2,qi:2}}]},
  {l:T('A promising stranger','一个有出息的外人'),out:[{w:1,t:T('A sharp-eyed young porter. Everyone thinks you are mad. In five years the business doubles.','一个眼尖的年轻脚夫。大家都说你疯了。五年后，家业翻了一番。'),c:'gold',fx:{fame:4,money:[40,150],deed:T('Handed on their life’s work to a stranger, wisely','慧眼识人，将毕生基业托付外人')}},{w:1,t:T('A charming young scholar, who sells it all within a year. You laugh, mostly.','一个讨人喜欢的年轻书生，一年就把家业卖光了。你大多时候是笑着的。'),c:'muted',fx:{happy:-3}}]},
  {l:T('Let it end with you','到我这儿就算了'),out:[{t:T('You close the doors yourself, pay everyone well, and sleep better than you have in years.','你亲手关了门，给每个人都发足了银子，睡得比这些年哪一晚都香。'),c:'muted',fx:{happy:5,money:[-60,-10],qi:2}}]}]});

I({id:'l2_banditmonk',age:[55,100],once:1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:4,age:s.age+rint(-5,5)});return c},text:c=>T(`An old monk, ${c.npc.en}, stops at your door. You know that scar: he once held a knife to your throat on a mountain road.`,`一个老和尚${c.npc.zh}在你门前停下。那道疤你认得：当年在山路上，他拿刀架过你的脖子。`),
 opts:[{l:T('Invite him in','请进门'),out:[{w:2,t:T('He tells you that you were the last man he robbed. Something about your face. He has prayed for you every morning since.','他说你是他抢的最后一个人。那天你的神情让他放下了刀。从那以后，他每天早上都为你念经。'),c:'good',fx:{happy:8,align:4,qi:3}},{w:1,t:T('He leaves you a string of prayer beads. Holding them, your breathing slows like a still pond.','他留给你一串念珠。握着它，你的呼吸慢得像一池静水。'),c:'gold',fx:{qi:6,lifespan:1}}]},
  {l:T('Close the door','关上门'),out:[{w:2,t:T('He bows to the door and walks on. You watch him through the crack until he is gone.','他对着门鞠了一躬，继续赶路。你从门缝里一直看着他走远。'),c:'muted',fx:{happy:-2}},{w:1,t:T('In the morning there is a small bag of silver on the step: exactly what he took, with interest.','第二天早上，门槛上放着一小袋银子：正是当年抢走的数，还加了利息。'),c:'good',fx:{money:[20,60]}}]},
  {l:T('Demand an apology','要他赔罪'),out:[{t:T('He kneels in the street without a word. You find you don’t want it after all, and pull him up.','他二话不说就在街上跪下了。你发现自己其实并不想要这个，又把他拉了起来。'),c:'good',fx:{align:3,happy:4}}]}]});

I({id:'l2_lateletter',age:[55,100],once:1,text:()=>T('A letter arrives, forty years late. The courier apologises: it was found behind a post-station wall.','一封信送到了，晚了四十年。送信的人连声道歉：是在驿站的墙缝里找到的。'),
 out:[{w:2,t:T('It is from your mother, written the year you left home. "Eat properly. Come back when you are tired." You sit with it all afternoon.','是母亲写的，那年你刚离家。"好好吃饭。累了就回来。"你捧着它坐了一整个下午。'),c:'muted',fx:{happy:-2,qi:3}},
  {w:1,t:T('It is a job offer from a sect that no longer exists. You laugh until you have to sit down.','是一个早已不存在的门派寄来的聘书。你笑得只好坐下。'),fx:{happy:5}},
  {w:1,t:T('It is a proposal of marriage from someone who, it turns out, still lives three villages away. You go. You have tea. It is enough.','是一封求亲信，写信的人原来还住在三个村子外。你去了，喝了杯茶。这就够了。'),c:'good',fx:{happy:8,meet:'friend',bond:70}},
  {w:1,t:T('It is a warning about an ambush on the road you took, forty years ago. You survived anyway. You feel oddly lucky all year.','是提醒你四十年前那条路上有埋伏的。你当年反正也活下来了。这一年你都觉得自己运气特别好。'),c:'good',fx:{talent:{luck:1},happy:3}}]});

I({id:'l2_foxdirections',age:[60,110],once:1,tags:['wander'],text:()=>T('On a mountain path at dusk, a fox sits up on its hind legs and asks you, very politely, the way to the capital.','黄昏的山路上，一只狐狸人立起来，非常客气地问你去京城怎么走。'),
 opts:[{l:T('Give good directions','好好指路'),out:[{w:2,t:T('It thanks you and trots away. At home you find your old aches have eased.','它道了谢，一溜小跑地走了。回到家，你发现多年的老伤都轻了。'),c:'gold',fx:{heal:30,maxHealth:3}},{w:1,t:T('It thanks you and offers you a drink from its gourd. You wake up under a tree, three days later, feeling twenty years younger.','它道了谢，请你喝它葫芦里的酒。你在一棵树下醒来，已是三天后，觉得年轻了二十岁。'),c:'gold',fx:{lifespan:2,happy:6}}]},
  {l:T('Ask what it wants in the capital','问它去京城干什么'),out:[{w:1,t:T('"To sit the imperial examination," it says, offended you would ask. You wish it luck.','"去考科举，"它说，似乎对你这么问很不满。你祝它高中。'),fx:{happy:5,smarts:2}},{w:1,t:T('"To settle an old score," it says, and shows its teeth. You decide not to ask more.','"去报一桩旧仇，"它说，露出了牙。你决定不再多问。'),c:'muted',fx:{qi:3}}]},
  {l:T('Decide you’re overtired and go home','断定自己太累了，回家'),out:[{t:T('Behind you, you hear it sigh: "Humans."','身后传来它的一声叹息："人啊。"'),c:'muted',fx:{happy:1}}]}]});

I({id:'l2_marketcheat',age:[60,110],cd:10,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:17,age:rint(20,35)});return c},text:c=>T(`A young peddler, ${c.npc.en}, short-changes you at the market, assuming an old fool won’t count.`,`年轻货郎${c.npc.zh}在集市上少找你钱，以为老糊涂了不会数。`),
 opts:[{l:T('Count it slowly in front of everyone','当众慢慢数'),out:[{w:2,t:T('You count very slowly, very loudly. A crowd gathers. The peddler pays twice to make it stop.','你数得很慢，嗓门很大。围观的人越来越多。货郎赔了两倍才让你停下。'),c:'good',fx:{money:4,happy:5}},{w:1,t:T('You lose count halfway. The crowd helps. It becomes a community event.','数到一半你忘了数到哪儿。围观的人都来帮忙。成了一场街坊盛事。'),fx:{happy:4}}]},
  {l:T('Catch his wrist','扣住他的手腕'),if:s=>power(s)>=20,out:[{t:c=>T(`Your fingers find the pressure point without thinking. ${c.npc.en} goes white and returns your change, and some of his own.`,`你的手指不假思索就扣住了穴位。${c.npc.zh}脸都白了，把钱找了回来，还搭上了自己的。`),c:'good',fx:{money:[5,15],fame:1}}]},
  {l:T('Let it go','算了'),out:[{w:1,t:T('A few coppers. Not worth the breath.','几文钱而已，不值得费口舌。'),c:'muted',fx:{money:-2}},{w:1,t:c=>T(`A week later ${c.npc.en} comes back, ashamed, and returns it. His mother made him.`,`一个星期后，${c.npc.zh}红着脸来还钱。是他娘逼他来的。`),c:'good',fx:{happy:3}}]}]});

I({id:'l2_strangecure',age:[55,110],cd:8,when:s=>!!s.ill,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([10,29,2,22]),age:rint(40,80)});return c},text:c=>T(`A wandering healer, ${c.npc.en}, hears of your illness and offers a cure: "Three live scorpions, steeped in wine, and you must sing while you drink it."`,`游方郎中${c.npc.zh}听说你病了，开了个方子："三只活蝎子泡酒，喝的时候还得唱歌。"`),
 opts:[{l:T('Drink it, singing','边唱边喝'),out:[{w:2,t:T('It is horrible. The singing is worse. But by the new moon you are well.','难喝得要命，唱得更难听。可到了新月，病就好了。'),c:'good',fx:{cure:1,heal:20,happy:3}},{w:1,t:T('It makes you very sick for a week, then very well. You are not sure which part was the cure.','喝下去先是大病一场，过了一个星期又好得出奇。你也说不清到底哪一步是治病的。'),fx:{cure:1,hurt:[5,12],cause:T('a scorpion tonic','蝎子药酒')}}]},
  {l:T('Ask for a more normal remedy','要个正常点的方子'),out:[{w:2,t:T('He sighs and writes you an ordinary prescription. It works, slowly.','他叹了口气，开了个普通方子。见效很慢，但见效了。'),fx:{heal:10,f:s=>{if(chance(.5))s.ill=null}}},{w:1,t:T('"Normal remedies are for normal people," he says, and leaves you a breathing exercise instead.','"正常的方子是给正常人用的，"他说，留给你一套吐纳法。'),c:'good',fx:{qi:5,heal:8}}]},
  {l:T('Send him away','打发走'),out:[{t:T('Your grandchild, overhearing, catches three scorpions anyway "just in case". Nobody sleeps well.','孙辈在旁边听见了，"以防万一"还是捉了三只蝎子来。全家都没睡好。'),c:'muted',fx:{happy:-1}}]}]});

I({id:'l2_reconcile',age:[55,100],cd:15,when:s=>living(s,['child','sibling','friend','sworn']).length>0,ctx:s=>{const all=living(s,['child','sibling','friend','sworn']);const low=all.filter(p=>p.bond<45);const p=pick(low.length?low:all);return{p,who:p.id}},text:c=>T(`You realise you and ${c.p.n.py} have not spoken properly in years, over something you can barely remember.`,`你忽然意识到，你和${c.p.n.cn}已经好些年没好好说过话了，为的是一件你都快记不清的事。`),
 opts:[{l:T('Go and knock on their door','亲自登门'),out:[{w:2,t:c=>T(`${c.p.n.py} opens the door, and after a long moment, steps aside to let you in.`,`${c.p.n.cn}开了门，愣了好半天，才侧身让你进去。`),c:'good',fx:{bond:25,happy:8}},{w:1,t:c=>T(`${c.p.n.py} was halfway down the road to your house at the same time. You meet in the middle.`,`原来${c.p.n.cn}同时也正往你家来。你们在半路上遇见了。`),c:'gold',fx:{bond:30,happy:10}}]},
  {l:T('Send a letter','写封信'),out:[{w:2,t:T('The reply takes a month. It is short. It is enough.','回信过了一个月才来。很短，但够了。'),c:'good',fx:{bond:15,happy:4}},{w:1,t:T('No reply comes. You send another. And another.','没有回音。你又写了一封，又一封。'),c:'muted',fx:{bond:5,happy:-2}}]},
  {l:T('Leave it be','由它去吧'),out:[{t:T('Pride is a heavy thing to carry at your age. You carry it anyway.','到了这把年纪，面子是很沉的东西。你还是扛着。'),c:'muted',fx:{happy:-4}}]}]});
}

/* incidents that tell the same story only get told once per life */
[['l2_coffinescort','s2_escortcoffin','q_coffin'],['l2_heir','b_heir']].forEach(g=>g.forEach(id=>{const i=INC_BY[id];if(!i)return;const w0=i.when;
  i.when=s=>g.every(o=>o===id||s.seen[o]==null)&&(!w0||w0(s))}));
